   104  int
   105  get_idna_map (uint32_t c, IDNAMap * map)
   106  {
   107    uint8_t *p;
   108
   109    if (c <= 0xFF)
   110      p =
   111        (uint8_t *)bsearch (&c, idna_map_8, sizeof (idna_map_8) / 5, 5,
   112                 (int (*)(const void *, const void *)) _compare_idna_map);
   113    else if (c <= 0xFFFF)
   114      p =
   115        (uint8_t *)bsearch (&c, idna_map_16, sizeof (idna_map_16) / 7, 7,
   116                 (int (*)(const void *, const void *)) _compare_idna_map);
   117    else if (c <= 0xFFFFFF)
   118      p =
   119        (uint8_t *)bsearch (&c, idna_map_24, sizeof (idna_map_24) / 8, 8,
   120                 (int (*)(const void *, const void *)) _compare_idna_map);
   121    else
   122      p = NULL;
   123
   124    if (!p)
   125      {
   126        memset (map, 0, sizeof (IDNAMap));
   127        return -1;
   128      }
   129
   130    _fill_map (c, p, map);
   131    return 0;
   132  }
   133
   134  int
   135  map_is (const IDNAMap * map, unsigned flags)
   136  {
   137    return (idna_flags[map->flag_index] & flags) == flags;
   138  }
   139
   140  static int G_GNUC_IDN2_ATTRIBUTE_PURE
   141  _compare_nfcqc_map (uint32_t * c, NFCQCMap * m2)
   142  {
   143    if (*c < m2->cp1)
   144      return -1;
   145    if (*c > m2->cp2)
   146      return 1;
   147    return 0;
   148  }
   149
   150  NFCQCMap *
   151  get_nfcqc_map (uint32_t c)
   152  {
   153    return (NFCQCMap *)bsearch (&c, nfcqc_map, countof (nfcqc_map), sizeof (NFCQCMap),
   154                    (int (*)(const void *, const void *)) _compare_nfcqc_map);
   155  }
   156
   157  /* copy 'n' codepoints from mapdata stream */
   158  int
   159  get_map_data (uint32_t * dst, const IDNAMap * map)
   160  {
   161    int n = map->nmappings;
   162    const uint8_t *src = mapdata + map->offset;
   163
   164    for (; n > 0; n--)
   165      {
   166        uint32_t cp = 0;
   167        do
   168          cp = (cp << 7) | (*src & 0x7F);
   169        while (*src++ & 0x80);
   170        *dst++ = cp;
   171      }
   172
   173    return map->nmappings;
   174  }

